begin;
do $$
declare owner_id uuid:=gen_random_uuid();viewer_id uuid:=gen_random_uuid();outsider_id uuid:=gen_random_uuid();s uuid:=gen_random_uuid();other_store uuid:=gen_random_uuid();ct uuid;cv uuid;other_ct uuid;other_cv uuid;r jsonb;draft_id uuid;policy_id uuid;decision_id uuid;case_id uuid;
begin
 insert into auth.users(id,email,raw_user_meta_data) values(owner_id,owner_id::text||'@example.invalid','{}'),(viewer_id,viewer_id::text||'@example.invalid','{}'),(outsider_id,outsider_id::text||'@example.invalid','{}');
 insert into public.platform_admins(user_id,role) values(owner_id,'owner'),(viewer_id,'viewer');
 insert into public.stores(id,name) values(s,'Support rollback test'),(other_store,'Other rollback test');
 insert into public.whatsapp_contacts(store_id,wa_id) values(s,'966500001234') returning id into ct;
 insert into public.whatsapp_conversations(store_id,contact_id) values(s,ct) returning id into cv;
 insert into public.whatsapp_contacts(store_id,wa_id) values(other_store,'966500001234') returning id into other_ct;
 insert into public.whatsapp_conversations(store_id,contact_id) values(other_store,other_ct) returning id into other_cv;
 insert into public.whatsapp_messages(store_id,conversation_id,external_message_id,direction,message_type,body,status,occurred_at) values(s,cv,'support-test-'||cv,'INBOUND','TEXT','email ahmed@example.com phone +966500001234 code 012345','RECEIVED',now());
 perform public.set_whatsapp_flow_state(cv,'AWAITING_ORDER',jsonb_build_object('verificationToken','must-never-leak','emailChallengeId','also-private'));
 assert exists(select 1 from private.journey_activity where conversation_id=cv and step='AWAITING_ORDER'),'step transition captured without context';
 assert not has_function_privilege('authenticated','public.record_journey_issue(uuid,text,text)','execute'),'browser cannot forge processing incidents';
 perform public.record_journey_issue(cv,'order_lookup_unavailable','test-issue');
 perform public.record_journey_issue(cv,'order_lookup_unavailable','test-issue');
 assert (select count(*) from private.journey_activity where conversation_id=cv and kind='issue')=1,'worker replay does not duplicate incident';
 assert not has_table_privilege('authenticated','private.journey_activity','select'),'no direct browser history access';
 assert not has_function_privilege('anon','public.staff_support_workspace(uuid,uuid)','execute'),'no anonymous staff reads';
 perform set_config('request.jwt.claims',jsonb_build_object('sub',outsider_id,'role','authenticated','aal','aal1')::text,true);
 begin perform public.staff_support_workspace(s); raise exception 'outsider got access'; exception when insufficient_privilege then null; end;
 insert into public.policy_versions(store_id,version_label,source_text,rules_snapshot,published_by) values(s,'support-test','test only','[]',owner_id) returning id into policy_id;
 insert into public.eligibility_decisions(store_id,policy_version_id,order_id,outcome,order_facts_snapshot,policy_snapshot) values(s,policy_id,'test-order','ELIGIBLE','{"email":"must-stay-private@example.invalid"}','{}') returning id into decision_id;
 insert into public.return_cases(store_id,decision_id,order_id,customer_snapshot,item_snapshot) values(s,decision_id,'test-order','{"email":"must-stay-private@example.invalid"}','{}') returning id into case_id;
 insert into private.whatsapp_case_links(conversation_id,case_id) values(cv,case_id);
 insert into public.support_tickets(store_id,conversation_id,source_message_id,kind,message) values(s,cv,'support-ticket-'||cv,'QUESTION','Private original ticket body must not appear');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',viewer_id,'role','authenticated','aal','aal1')::text,true);
 r:=public.staff_support_workspace(s);
 assert r->'store'->>'id'=s::text,'staff view selected store';
 assert jsonb_array_length(r->'cases')=1 and jsonb_array_length(r->'tickets')=1,'case and ticket destinations included';
 assert r->'cases'->0->'conversation_ids' @> to_jsonb(array[cv]),'case correlated with its conversation';
 assert r::text not like '%must-stay-private@example.invalid%' and r::text not like '%Private original ticket body%','private case and ticket content excluded';
 assert r::text not like '%ahmed@example.com%' and r::text not like '%966500001234%' and r::text not like '%012345%','contacts and OTP masked';
 assert r::text not like '%must-never-leak%' and r::text not like '%also-private%','private flow context excluded';
 assert exists(select 1 from public.platform_admin_events where actor_user_id=viewer_id and entity_id=s and event_type='SUPPORT_WORKSPACE_VIEWED'),'access audited';
 perform public.staff_support_workspace(s);
 assert (select count(*) from public.platform_admin_events where actor_user_id=viewer_id and entity_id=s and event_type='SUPPORT_WORKSPACE_VIEWED')=1,'polling grouped';
 begin perform public.staff_support_workspace(s,other_cv); raise exception 'cross-store conversation allowed'; exception when raise_exception then if sqlerrm<>'conversation_mismatch' then raise; end if; end;
 begin perform public.staff_prepare_knowledge(s,'Delivery','Merchant supplied facts','DELIVERY','en');raise exception 'viewer wrote a draft';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',owner_id,'role','authenticated','aal','aal1')::text,true);
 draft_id:=public.staff_prepare_knowledge(s,'Delivery','Merchant supplied facts','DELIVERY','en');
 assert exists(select 1 from public.store_knowledge where id=draft_id and not published and approved_by is null),'owner can only prepare unpublished draft';
 assert exists(select 1 from public.audit_events where entity_id=draft_id and event_type='knowledge.staff.draft_prepared'),'draft provenance audited';
 begin perform public.record_workspace_issue(s,'knowledge','save_failed');raise exception 'nonmember wrote merchant issue';exception when insufficient_privilege then null;end;
 assert not exists(select 1 from public.memberships where store_id=s and user_id in (owner_id,viewer_id)),'no impersonation memberships';
end $$;
rollback;
